-- 009_semilla_diagnosticos.sql
-- Semilla del catalogo de diagnosticos pre-redactados y repuestos frecuentes de INDUSTEC
-- (mantenimiento de cocinas industriales de KFC en Ecuador).
--
-- Por que existe: los tecnicos redactan el 'trabajo realizado' de cada OT desde cero,
-- repitiendo a mano las mismas fallas y los mismos repuestos una y otra vez. Este catalogo
-- permite elegir un diagnostico pre-redactado (con su texto tecnico y sus repuestos
-- frecuentes sugeridos) y agilizar el cierre de la orden de trabajo.
--
-- De donde sale: mineria de 7.863 filas reales de los planes de zona 2025-2026 de INDUSTEC
-- (23 familias de equipo, con los textos de 'trabajo realizado' y los repuestos mas
-- repetidos por familia). Los diagnosticos fueron redactados a partir de esos textos reales,
-- generalizando variantes de una misma falla; no se inventaron fallas sin respaldo.
--
-- Como se aplica: php aplicar_sql.php sql/009_semilla_diagnosticos.sql
-- Debe aplicarse despues de 009_pulido_piloto.sql (no crea tablas, solo inserta catalogo).
-- Es idempotente: puede volver a ejecutarse sin duplicar filas, gracias a
-- ON DUPLICATE KEY UPDATE sobre las llaves primarias (familia, codigo).

-- 1) Familias de equipo (23), orden por volumen real de casos (1 = FREIDORA, la de mayor volumen).
ON DUPLICATE KEY UPDATE patron = VALUES(patron), orden = VALUES(orden);

-- 2) Repuestos frecuentes por familia (109 filas), una fila por repuesto real (no por frase
-- completa de la orden de trabajo). numero_parte solo cuando el texto minado lo trae.
ON DUPLICATE KEY UPDATE descripcion = VALUES(descripcion), numero_parte = VALUES(numero_parte), marca = VALUES(marca), unidad = VALUES(unidad), orden = VALUES(orden);

-- 3) Diagnosticos pre-redactados (159 filas): >= 8 por cada una de las 14 familias de mayor
-- volumen y >= 4 en las 9 restantes. Formato del texto: Sintoma / Causa probable / Accion.
ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), texto = VALUES(texto), partes_frecuentes = VALUES(partes_frecuentes), orden = VALUES(orden);
