INSERT INTO diagnosticos (codigo, familia, titulo, texto, partes_frecuentes, orden) VALUES
('FRE-01', 'FREIDORA', 'No enciende: termopila rota o reventada', 'Sintoma: el piloto no se mantiene encendido o el equipo no enciende los quemadores. Causa probable: termocupla reventada o en mal estado que no genera la senal de seguridad a la valvula de gas. Accion: retirar los quemadores, reemplazar la termocupla y verificar continuidad antes de cerrar el equipo.', '["REP-001", "REP-002"]', 1),
('FRE-02', 'FREIDORA', 'Fuga de gas en valvula de paso o manguera', 'Sintoma: olor a gas o fuga audible en la valvula de paso o en la manguera de alimentacion. Causa probable: manguera deteriorada o acople sin sellador de roscas. Accion: reemplazar manguera y valvula, sellar roscas con teflon amarillo y gastop, y probar hermeticidad antes de habilitar el equipo.', '["REP-005", "REP-006", "REP-007", "REP-008", "REP-009"]', 2),
('FRE-03', 'FREIDORA', 'No sube el aceite por falta de empaque del tanque', 'Sintoma: el aceite no sube o sube muy lento durante el llenado. Causa probable: falta o deterioro del empaque del tanque de aceite, lo que impide que la bomba genere succion. Accion: instalar empaque nuevo en el tanque de aceite y verificar el funcionamiento de la bomba.', '["REP-003"]', 3),
('FRE-04', 'FREIDORA', 'Fuga de aceite por retenedor de bomba desgastado', 'Sintoma: goteo de aceite en la base de la freidora durante la filtracion. Causa probable: retenedor de la bomba de aceite desgastado o fuera de su alojamiento. Accion: desmontar el cuerpo de la bomba, reemplazar el retenedor y verificar que no existan fugas tras el rearmado.', '["REP-004"]', 4),
('FRE-05', 'FREIDORA', 'Sistema de filtrado de aceite no trabaja correctamente', 'Sintoma: el sistema de filtrado de aceite no funciona con normalidad. Causa probable: desgaste del sello mecanico y de la valvula check del sistema de filtrado. Accion: reemplazar el kit de sello mecanico y la valvula check, y realizar una prueba completa de filtrado.', '["REP-014"]', 5),
('FRE-06', 'FREIDORA', 'Fuga en valvula de drenaje (drain)', 'Sintoma: fuga de aceite en la valvula de drenaje al accionar la palanca. Causa probable: desgaste del asiento o del ensamblaje de la valvula drain. Accion: desmontar la palanca y el ensamblaje de la valvula de drenaje, reemplazarlo y probar el cierre hermetico.', '["REP-010"]', 6),
('FRE-07', 'FREIDORA', 'Panel de control desprogramado, error E-41', 'Sintoma: el panel de control se desprograma y muestra el error E-41 de memoria del controlador. Causa probable: fallo interno de la tarjeta PCB del controlador. Accion: reprogramar el controlador y, si el error persiste, reemplazar la tarjeta PCB.', NULL, 7),
('FRE-08', 'FREIDORA', 'Cable o enchufe de alimentacion en mal estado', 'Sintoma: el equipo no enciende o el breaker se dispara al mover el equipo. Causa probable: cable de alimentacion roto o enchufe suelto que hace falso contacto con la acometida. Accion: reemplazar el tramo de cable danado, el enchufe, y asegurar la conexion a la acometida.', '["REP-013"]', 8),
('FRE-09', 'FREIDORA', 'Quemadores no encienden por perilla o valvula unitrol sucia', 'Sintoma: los quemadores no encienden o no mantienen la posicion correcta de encendido. Causa probable: perilla de la valvula unitrol desgastada o sucia, o shiglores obstruidos. Accion: limpiar shiglores y valvula unitrol, y reemplazar la perilla si no retiene la posicion.', NULL, 9),
('FRE-10', 'FREIDORA', 'Blower con ruido por jaula rozando la estructura', 'Sintoma: sonido anormal en el blower del quemador. Causa probable: la jaula del blower toca la estructura o el aspa esta desalineada. Accion: desmontar el blower, realinear o reemplazar el conjunto y verificar que gire libre.', '["REP-012"]', 10),
('REF-01', 'REFRIGERADOR', 'Empaque de puerta deteriorado, pierde hermeticidad', 'Sintoma: el equipo pierde temperatura y el empaque de la puerta se ve suelto o rasgado. Causa probable: empaque de puerta deteriorado por uso que rompe la hermeticidad. Accion: tomar medidas exactas de la puerta y reemplazar el empaque por uno del mismo modelo.', '["REP-016"]', 1),
('REF-02', 'REFRIGERADOR', 'Evaporador bloqueado por hielo', 'Sintoma: el equipo no llega a la temperatura correcta y hace ruido por hielo acumulado. Causa probable: evaporador bloqueado por escarcha, generalmente por empaque de puerta en mal estado que deja entrar humedad. Accion: desbloquear el evaporador y revisar el empaque de la puerta.', '["REP-016"]', 2),
('REF-03', 'REFRIGERADOR', 'Compresor no arranca por kit de arranque defectuoso', 'Sintoma: el compresor no enciende aunque el equipo tiene alimentacion electrica. Causa probable: kit de arranque (rele y protector termico) defectuoso que impide el arranque del motor compresor. Accion: confirmar con arranque directo, reemplazar el kit de arranque y probar funcionamiento.', '["REP-019"]', 3),
('REF-04', 'REFRIGERADOR', 'Controlador electronico danado', 'Sintoma: el equipo presenta condensacion en el evaporador y no mantiene la temperatura configurada. Causa probable: dano electronico en el controlador digital (full gauge). Accion: desbloquear el evaporador y reemplazar el controlador digital danado.', '["REP-018"]', 4),
('REF-05', 'REFRIGERADOR', 'Clips de estante rotos o faltantes', 'Sintoma: los estantes internos no se sujetan correctamente. Causa probable: clips plasticos de sujecion de estantes rotos o faltantes por desgaste. Accion: reemplazar los clips plasticos por repuestos originales del fabricante.', '["REP-020"]', 5),
('REF-06', 'REFRIGERADOR', 'Fuga de gas refrigerante en presostato', 'Sintoma: el equipo no llega a temperatura pese a que el motor ventilador funciona con normalidad. Causa probable: fuga de gas refrigerante localizada en el presostato de alta o baja presion. Accion: localizar la fuga, reemplazar el presostato, cargar gas y probar presiones de trabajo.', '["REP-021"]', 6),
('REF-07', 'REFRIGERADOR', 'Sonido fuerte por hielo golpeando el ventilador interno', 'Sintoma: sonido fuerte dentro del equipo. Causa probable: el ventilador interno golpea una capa de hielo generada por bloqueo del evaporador. Accion: desbloquear el hielo acumulado, verificar giro libre del ventilador y revisar el empaque de la puerta.', '["REP-016"]', 7),
('REF-08', 'REFRIGERADOR', 'Pernos de base de ventiladores de cuarto frio flojos', 'Sintoma: vibracion y ruido en los ventiladores del cuarto frio. Causa probable: pernos de la base de los motores ventiladores flojos por vibracion continua. Accion: colocar rodelas con aislante y ajustar pernos y tuercas de la base.', NULL, 8),
('REF-09', 'REFRIGERADOR', 'Cortinas de cuarto frio deterioradas', 'Sintoma: perdida de frio al ingresar al cuarto frio. Causa probable: cortinas plasticas de la puerta del cuarto frio rotas o deterioradas por el uso. Accion: medir el vano de la puerta e instalar cortinas nuevas del ancho y largo correspondiente.', '["REP-023"]', 9),
('REF-10', 'REFRIGERADOR', 'Compresor con bobinas aterrizadas', 'Sintoma: el compresor no enciende y el breaker se dispara. Causa probable: bobinas internas del compresor aterrizadas por falla electrica interna. Accion: confirmar el aterrizaje con megado, reemplazar el compresor segun placa del equipo y realizar vacio del sistema.', '["REP-017"]', 10),
('HIE-01', 'MAQUINA DE HIELO', 'Hielo amarillo por sarro o calcificacion', 'Sintoma: el hielo sale amarillento y con sabor extrano. Causa probable: acumulacion de sarro (calcio) en flautas, bandeja y tuberias de distribucion de agua. Accion: realizar limpieza y descalcificacion completa con el kit correspondiente y sanitizar el equipo.', '["REP-025", "REP-026", "REP-029"]', 1),
('HIE-02', 'MAQUINA DE HIELO', 'Sensor de nivel o de grosor de hielo danado', 'Sintoma: el equipo no produce hielo o detiene la produccion de forma anomala. Causa probable: sensor de nivel de agua o de grosor de hielo danado o sucio. Accion: limpiar los pines del sensor y, si no recupera continuidad, reemplazar el sensor de nivel de agua.', '["REP-027", "REP-028"]', 2),
('HIE-03', 'MAQUINA DE HIELO', 'Panel touch no enciende ni responde', 'Sintoma: el panel tactil no enciende y el equipo no produce hielo. Causa probable: falla del panel touch o de su continuidad interna segun el manual del fabricante. Accion: verificar continuidad del panel tactil y reemplazar el conjunto de marco y panel digital.', '["REP-030"]', 3),
('HIE-04', 'MAQUINA DE HIELO', 'Filtracion de agua en bandeja de subenfriamiento', 'Sintoma: fuga de agua en la bandeja de subenfriamiento del equipo. Causa probable: sellos o uniones de la bandeja deteriorados. Accion: sellar la fuga con material asfaltico autoadhesivo y verificar que no se repita tras la sanitizacion.', NULL, 4),
('HIE-05', 'MAQUINA DE HIELO', 'Falla en sensor de agua o boya del bin', 'Sintoma: el equipo bota solo agua o la bandeja de recoleccion se llena sin producir hielo. Causa probable: sonda o boya de nivel de agua sucia u obstruida por sarro. Accion: limpiar la sonda de agua y las boyas, y reemplazar si no recupera la senal.', '["REP-027"]', 5),
('HIE-06', 'MAQUINA DE HIELO', 'Fuga de agua por manguera de desague doblada', 'Sintoma: el equipo derrama agua por la parte trasera. Causa probable: manguera de desague doblada u obstruida que impide el drenaje correcto. Accion: enderezar o reemplazar la manguera de desague y verificar el flujo de drenaje.', NULL, 6),
('HIE-07', 'MAQUINA DE HIELO', 'Valvula solenoide de agua defectuosa', 'Sintoma: el equipo no llena agua correctamente para el ciclo de fabricacion. Causa probable: valvula solenoide de entrada de agua de 120V defectuosa. Accion: reemplazar la valvula solenoide y verificar el ciclo completo de llenado.', '["REP-031"]', 7),
('HIE-08', 'MAQUINA DE HIELO', 'Compresor sin compresion o fuga de refrigerante', 'Sintoma: el equipo no enfria ni produce hielo. Causa probable: fuga de gas refrigerante R410A o compresor sin compresion. Accion: localizar la fuga, reparar, cargar refrigerante con el kit de suelda y varillas, y verificar presiones de trabajo.', '["REP-033"]', 8),
('HIE-09', 'MAQUINA DE HIELO', 'Tarjeta electronica de control danada', 'Sintoma: el equipo no enciende o no completa el ciclo de fabricacion de hielo. Causa probable: dano en la tarjeta electronica de control. Accion: verificar voltajes de entrada y salida en la tarjeta y reemplazarla si no responde a los parametros del manual.', NULL, 9),
('CON-01', 'CONGELADOR', 'Empaque de puerta deteriorado', 'Sintoma: el congelador no llega a temperatura y presenta escarcha. Causa probable: empaque de puerta en mal estado que rompe la hermeticidad. Accion: tomar medidas y reemplazar el empaque por el modelo correspondiente.', '["REP-034"]', 1),
('CON-02', 'CONGELADOR', 'Compresor con bobinas aterrizadas o danado', 'Sintoma: el compresor no enciende y provoca disparo del breaker. Causa probable: bobinas internas del compresor aterrizadas o compresor danado. Accion: confirmar con megado, reemplazar el compresor segun placa del equipo, y realizar vacio y carga de refrigerante.', '["REP-035", "REP-037"]', 2),
('CON-03', 'CONGELADOR', 'Motor ventilador de condensadora danado', 'Sintoma: el equipo no llega a temperatura y el ventilador de la unidad condensadora gira despacio o no gira. Causa probable: motor ventilador danado o recalentado. Accion: reemplazar el motor ventilador y verificar el giro libre del aspa.', '["REP-036"]', 3),
('CON-04', 'CONGELADOR', 'Cortocircuito en enchufe o toma por variacion de voltaje', 'Sintoma: el equipo no enciende tras una variacion de voltaje. Causa probable: cortocircuito en el enchufe o el toma de corriente por sobretension. Accion: reemplazar enchufe y toma corriente, y recomendar la instalacion de un protector de voltaje.', NULL, 4),
('CON-05', 'CONGELADOR', 'Controlador digital sin senal (full gauge)', 'Sintoma: el equipo no llega a temperatura y el controlador digital no recibe senal. Causa probable: falla del controlador full gauge o de su sonda asociada. Accion: verificar la sonda y reemplazar el controlador full gauge TC-900.', '["REP-038"]', 5),
('CON-06', 'CONGELADOR', 'Kit de arranque y pines de compresor en mal estado', 'Sintoma: el equipo no llega a temperatura y el compresor no arranca. Causa probable: kit de arranque (capacitor y rele) y pines del compresor desgastados. Accion: reemplazar el kit de arranque CSR y limpiar o reemplazar los pines de conexion del compresor.', '["REP-039"]', 6),
('CON-07', 'CONGELADOR', 'Puerta sin empaque bloquea el evaporador con hielo', 'Sintoma: el evaporador se bloquea con hielo y el equipo no llega a temperatura. Causa probable: puerta sin empaque que permite el ingreso de humedad al gabinete. Accion: desbloquear el evaporador e instalar empaque nuevo en la puerta.', '["REP-034"]', 7),
('CON-08', 'CONGELADOR', 'Recalentamiento del motor-compresor', 'Sintoma: el motor-compresor se recalienta y no funciona correctamente. Causa probable: amperaje elevado por sobrecarga o kit de arranque defectuoso. Accion: verificar amperaje contra placa, y reemplazar kit de arranque y capacitores si el consumo es mayor al nominal.', '["REP-039"]', 8),
('HOL-01', 'HOLDING CABINET', 'Empaque de puerta en mal estado', 'Sintoma: el holding cabinet pierde temperatura por las puertas. Causa probable: empaque de puerta desgastado o roto que rompe la hermeticidad del gabinete. Accion: medir y reemplazar el empaque de puerta segun el modelo HC-900 o HC-903.', '["REP-041"]', 1),
('HOL-02', 'HOLDING CABINET', 'Switch de encendido en corto', 'Sintoma: el equipo no enciende o presenta cortocircuito al accionar el switch. Causa probable: switch interruptor conmutador danado internamente. Accion: reemplazar el switch de encendido y verificar el circuito de alimentacion.', '["REP-040"]', 2),
('HOL-03', 'HOLDING CABINET', 'Resistencia explotada internamente', 'Sintoma: el equipo no llega a la temperatura de retencion requerida. Causa probable: resistencia interna explotada o sin continuidad. Accion: medir la resistencia con multimetro, reemplazarla, instalar y verificar funcionamiento.', '["REP-043"]', 3),
('HOL-04', 'HOLDING CABINET', 'Motor ventilador con bobinas recalentadas', 'Sintoma: el motor ventilador no funciona o hace ruido y el equipo no llega a temperatura. Causa probable: bobinas del motor ventilador recalentadas por desgaste de rodamientos. Accion: limpiar y lubricar de forma provisional, y reemplazar el motor ventilador con su lana de fibra ceramica.', '["REP-042"]', 4),
('HOL-05', 'HOLDING CABINET', 'Lana ceramica de aislamiento deteriorada', 'Sintoma: el equipo no retiene la temperatura interna de forma uniforme. Causa probable: lana de fibra ceramica de aislamiento termico deteriorada. Accion: retirar la lana antigua y colocar lana ceramica nueva en la cavidad del gabinete.', '["REP-042"]', 5),
('HOL-06', 'HOLDING CABINET', 'Clavija de alimentacion derretida', 'Sintoma: el equipo no enciende. Causa probable: clavija de alimentacion derretida que impide un buen contacto con el tomacorriente. Accion: reemplazar la clavija y el cable de alimentacion de 12 AWG.', '["REP-045"]', 6),
('HOL-07', 'HOLDING CABINET', 'Sonda de temperatura RTD danada (errores E4 o E6)', 'Sintoma: el panel muestra errores de sobrecalentamiento o de sonda de temperatura. Causa probable: sonda de temperatura RTD danada o mal conectada. Accion: reemplazar la sonda RTD y verificar la lectura en el panel de control.', '["REP-044"]', 7),
('HOL-08', 'HOLDING CABINET', 'Cableado de alimentacion deteriorado', 'Sintoma: el equipo presenta fallas intermitentes de encendido. Causa probable: cableado de alimentacion deteriorado por el uso y el calor del gabinete. Accion: reemplazar el cable de alimentacion de 12 AWG completo con sus tres conductores.', '["REP-045"]', 8),
('HOR-01', 'HORNO', 'Fugas de flama en quemadores por ceramicas rotas', 'Sintoma: fugas de flama hacia arriba y lenguetas de fuego en los quemadores. Causa probable: ceramicas de los quemadores rotas o mallas fisuradas. Accion: desmontar los quemadores, reemplazar ceramicas y mallas, y calibrar la flama.', '["REP-048"]', 1),
('HOR-02', 'HORNO', 'Malla de quemador fisurada (contra explosiones)', 'Sintoma: contra explosiones al encender los quemadores. Causa probable: mallas de los quemadores fisuradas que dejan pasar exceso de gas antes de encender. Accion: reemplazar las mallas y colocar lana de vidrio en el quemador afectado.', '["REP-048"]', 2),
('HOR-03', 'HORNO', 'Manguera de gas inadecuada o sin ataque rapido', 'Sintoma: riesgo de fuga en la acometida de gas del horno. Causa probable: manguera de gas no apta o sin ataque rapido instalado. Accion: instalar manguera con ataque rapido del diametro correcto y sellar con teflon amarillo.', '["REP-047"]', 3),
('HOR-04', 'HORNO', 'Tornillos de sujecion de quemadores oxidados', 'Sintoma: los quemadores presentan holgura o desalineacion. Causa probable: tornillos de sujecion oxidados que pierden torque. Accion: reemplazar los tornillos por repuestos originales y ajustar el conjunto de quemadores.', '["REP-049"]', 4),
('HOR-05', 'HORNO', 'Shiglores sucios con acumulacion de grasa', 'Sintoma: los quemadores no tienen fuerza de llama. Causa probable: shiglores y tuberia de cobre con acumulacion de grasa que restringe el paso de gas. Accion: desmontar y limpiar el conjunto de shiglores y la tuberia de cobre.', '["REP-052"]', 5),
('HOR-06', 'HORNO', 'Valvula de gas en mal estado', 'Sintoma: los quemadores no encienden con fuerza uniforme. Causa probable: valvula de gas del horno en mal estado o con fuga interna. Accion: reemplazar la valvula de gas y verificar la presion de trabajo.', '["REP-051"]', 6),
('HOR-07', 'HORNO', 'Switch de paso de gas danado (no enciende)', 'Sintoma: el horno no enciende. Causa probable: switch electrico de paso de gas danado. Accion: corregir la anomalia de forma provisional y reemplazar el switch de paso de gas de manera urgente.', NULL, 7),
('HOR-08', 'HORNO', 'Empaque de puerta roto', 'Sintoma: perdida de calor por la puerta del horno. Causa probable: empaque principal de la puerta roto o desprendido. Accion: reemplazar el empaque de puerta y verificar el cierre hermetico.', NULL, 8),
('HOR-09', 'HORNO', 'Magnetron danado en horno tipo turbo (error F3)', 'Sintoma: error F3 relacionado al circuito del magnetron. Causa probable: magnetron danado o antena de microondas desgastada. Accion: reemplazar el kit de servicio del magnetron y el filtro de aire, y limpiar los ventiladores.', NULL, 9),
('MRF-01', 'MESA REFRIGERADA', 'Empaque de puerta o cajon deteriorado', 'Sintoma: la mesa refrigerada pierde temperatura. Causa probable: empaque de puerta o de cajonera deteriorado o faltante. Accion: tomar medidas exactas y reemplazar el empaque segun el modelo de la mesa.', '["REP-053"]', 1),
('MRF-02', 'MESA REFRIGERADA', 'Junta de cajon en mal estado', 'Sintoma: perdida de frio en el compartimento de cajones. Causa probable: junta de cajon desgastada que no sella correctamente. Accion: reemplazar la junta de cajon y verificar el cierre hermetico.', '["REP-054"]', 2),
('MRF-03', 'MESA REFRIGERADA', 'Breaker matic saltado, el equipo no enciende', 'Sintoma: el equipo no enciende o no llega a temperatura. Causa probable: breaker matic de proteccion saltado por sobrecarga o falla de aislamiento. Accion: revisar el circuito, corregir la falla y reemplazar el breaker matic si no restablece.', '["REP-055"]', 3),
('MRF-04', 'MESA REFRIGERADA', 'Riel de cajon desgastado (el cajon no cierra)', 'Sintoma: el cajon no abre ni cierra correctamente. Causa probable: riel de cajon salido de su posicion y ruedas desgastadas. Accion: reemplazar el riel bajo modelo y ajustar su alineacion.', NULL, 4),
('MRF-05', 'MESA REFRIGERADA', 'Compresor sin refrigeracion', 'Sintoma: la mesa refrigerada no baja de temperatura. Causa probable: compresor sin compresion o fuga de gas refrigerante R134a. Accion: reemplazar el compresor y el filtro deshidratador, y cargar refrigerante segun el sistema.', '["REP-056"]', 5),
('MRF-06', 'MESA REFRIGERADA', 'Motor ventilador trasero con obstruccion', 'Sintoma: sonido extrano en la parte trasera del equipo. Causa probable: motor ventilador trasero obstruido o desalineado. Accion: acomodar o reemplazar el motor ventilador y verificar el giro libre.', NULL, 6),
('MRF-07', 'MESA REFRIGERADA', 'Kit de arranque en mal estado (no baja temperatura)', 'Sintoma: el equipo no baja de temperatura. Causa probable: kit de arranque del compresor en mal estado con bobinas desfasadas. Accion: reemplazar el kit de arranque y realizar prueba de amperaje del compresor.', NULL, 7),
('MRF-08', 'MESA REFRIGERADA', 'Parante de puertas desalineado', 'Sintoma: el equipo no llega a la temperatura requerida. Causa probable: parante que une las puertas fuera de posicion, rompiendo la hermeticidad. Accion: realinear el parante y verificar el sello de las puertas.', NULL, 8),
('LIC-01', 'LICUADORA', 'Clutch desgastado (sonido fuerte, no gira)', 'Sintoma: sonido fuerte al encender o la licuadora no gira el vaso. Causa probable: clutch de acople desgastado por uso intensivo. Accion: reemplazar el clutch y probar el acople con el vaso.', '["REP-057"]', 1),
('LIC-02', 'LICUADORA', 'Cuchillas desgastadas (licua lento)', 'Sintoma: la licuadora tarda demasiado en licuar o licua de forma irregular. Causa probable: conjunto de cuchillas desgastado. Accion: reemplazar el conjunto de cuchillas Advance y probar el ciclo de licuado.', '["REP-058"]', 2),
('LIC-03', 'LICUADORA', 'Conjunto de vaso de accionamiento desgastado', 'Sintoma: la licuadora no transmite el giro correctamente al vaso. Causa probable: conjunto de vaso de accionamiento (drive socket) desgastado. Accion: reemplazar el conjunto de accionamiento y verificar el acople con el clutch.', '["REP-059"]', 3),
('LIC-04', 'LICUADORA', 'Junta de aislamiento deteriorada (fuga por la base)', 'Sintoma: fuga de liquido por la base del vaso. Causa probable: junta de aislamiento en mal estado. Accion: reemplazar la junta de aislamiento y probar la hermeticidad del vaso.', '["REP-060"]', 4),
('LIC-05', 'LICUADORA', 'Carbones de motor desgastados', 'Sintoma: el motor pierde fuerza o no gira con normalidad. Causa probable: carbones de motor desgastados por uso prolongado. Accion: reemplazar los carbones de motor y verificar el consumo electrico.', '["REP-061"]', 5),
('LIC-06', 'LICUADORA', 'Cables pelados en el sistema electrico interno', 'Sintoma: la licuadora se acciona sola o de forma intermitente. Causa probable: cables internos pelados que generan falso contacto. Accion: reemplazar el tramo de cable danado y aislar las conexiones internas.', NULL, 6),
('LIC-07', 'LICUADORA', 'Tarjeta de control con dano por humedad', 'Sintoma: la licuadora no enciende o no responde al panel de control. Causa probable: agua ingresada a la tarjeta de control que genera corrosion en las pistas. Accion: limpiar la tarjeta, verificar continuidad y reemplazarla si no recupera funcionamiento.', NULL, 7),
('LIC-08', 'LICUADORA', 'Engranes o pinon de vaso desgastados', 'Sintoma: la licuadora hace ruido fuerte y no trabaja correctamente. Causa probable: pinon de engrane del vaso desgastado junto con el clutch. Accion: reemplazar el clutch y el pinon de engrane desgastado.', '["REP-057"]', 8),
('CAF-01', 'MAQUINA DE CAFE', 'Goteo en ducha por empaque cristalizado', 'Sintoma: goteo constante en la ducha del grupo de cafe. Causa probable: junta de grupo (gasket) cristalizada por el calor y el uso. Accion: reemplazar la junta de grupo y probar la extraccion.', '["REP-062"]', 1),
('CAF-02', 'MAQUINA DE CAFE', 'Switch de encendido danado (no enciende)', 'Sintoma: la cafetera no enciende. Causa probable: switch de encendido de 4 pines en mal estado internamente. Accion: reemplazar el switch de encendido y verificar el ingreso de voltaje.', '["REP-063"]', 2),
('CAF-03', 'MAQUINA DE CAFE', 'Sensor de temperatura de caldera defectuoso', 'Sintoma: el equipo mantiene la temperatura pero no calienta correctamente el cafe. Causa probable: sensor interno de temperatura de la caldera danado. Accion: reemplazar el sensor de temperatura y verificar el amperaje de la resistencia.', '["REP-065"]', 3),
('CAF-04', 'MAQUINA DE CAFE', 'Valvula de alivio de presion defectuosa', 'Sintoma: presion irregular en la caldera de la cafetera. Causa probable: valvula de alivio de presion defectuosa o mal calibrada. Accion: reemplazar la valvula de alivio y verificar la presion de trabajo de la caldera.', '["REP-064"]', 4),
('CAF-05', 'MAQUINA DE CAFE', 'Electrovalvula solenoide de agua defectuosa', 'Sintoma: filtracion de agua por el sistema de ducha. Causa probable: electrovalvula solenoide de agua en mal estado. Accion: reemplazar la electrovalvula solenoide y probar el ciclo de agua caliente.', '["REP-066"]', 5),
('CAF-06', 'MAQUINA DE CAFE', 'Contramuelle roto (palanca de grupo)', 'Sintoma: la palanca del grupo no retorna correctamente. Causa probable: contramuelle de la cimbra roto. Accion: reemplazar el contramuelle y verificar el mecanismo de la palanca.', NULL, 6),
('CAF-07', 'MAQUINA DE CAFE', 'Motor de molino trabado por cafe solidificado', 'Sintoma: el molino no muele el cafe. Causa probable: motor del molino trabado por acumulacion de cafe solidificado. Accion: desmontar y limpiar el mecanismo del molino, y verificar el giro libre del motor.', NULL, 7),
('CAF-08', 'MAQUINA DE CAFE', 'Calcificacion interna, requiere descalcificacion', 'Sintoma: empaques cristalizados y bajo rendimiento en la extraccion. Causa probable: acumulacion de sarro por falta de descalcificacion periodica. Accion: aplicar descalcificante segun el manual y reemplazar los empaques cristalizados.', '["REP-067", "REP-062"]', 8),
('HEL-01', 'MAQUINA DE HELADO', 'Esparrago o perno de mascarilla suelto', 'Sintoma: el equipo trabaja de forma ineficiente por ingreso de aire. Causa probable: esparrago o perno de sujecion de la mascarilla suelto o a punto de ruptura. Accion: reemplazar el esparrago o los pernos y ajustar la mascarilla.', '["REP-068", "REP-069"]', 1),
('HEL-02', 'MAQUINA DE HELADO', 'Fuga de refrigerante en el compresor', 'Sintoma: el equipo no llega a temperatura en las tolvas. Causa probable: fuga de gas refrigerante que reduce la capacidad del compresor. Accion: localizar la fuga, reparar, cargar refrigerante y verificar la presion de trabajo.', '["REP-070", "REP-071"]', 2),
('HEL-03', 'MAQUINA DE HELADO', 'Tarjeta de mando no desactiva el compresor', 'Sintoma: el producto se congela en exceso dentro de la tolva. Causa probable: tarjeta de mando que no desactiva el compresor en el punto de consistencia correcto. Accion: verificar los parametros de viscosidad y temperatura, y reemplazar la tarjeta si no responde.', NULL, 3),
('HEL-04', 'MAQUINA DE HELADO', 'Motor de bomba de circulacion no arranca', 'Sintoma: el equipo no hace circular la mezcla en la tolva. Causa probable: motor de la bomba de circulacion que no entra en funcionamiento. Accion: verificar con el boton de comprobacion y reemplazar el motor de la bomba si no arranca.', NULL, 4),
('HEL-05', 'MAQUINA DE HELADO', 'Bandas de transmision desgastadas (olor a quemado)', 'Sintoma: olor a quemado durante la operacion del equipo. Causa probable: bandas de transmision desgastadas por friccion excesiva. Accion: reemplazar las bandas de transmision y verificar la tension de la polea.', NULL, 5),
('HEL-06', 'MAQUINA DE HELADO', 'Protector termico del motor activado', 'Sintoma: error en pantalla y el equipo se detiene. Causa probable: protector termico del motor activado por sobrecarga, con contacto danado. Accion: reiniciar el protector, reemplazar el contacto danado y verificar el consumo del motor.', NULL, 6),
('HEL-07', 'MAQUINA DE HELADO', 'Empaque de baston mixto roto (filtracion entre tolvas)', 'Sintoma: filtracion de mezcla de una tolva hacia la otra. Causa probable: empaque del baston mixto roto o desgastado. Accion: reemplazar el empaque del baston mixto y probar el sellado entre tolvas.', NULL, 7),
('HEL-08', 'MAQUINA DE HELADO', 'Puerta de vidrio rota', 'Sintoma: la puerta de exhibicion del equipo presenta rotura del vidrio. Causa probable: golpe o fatiga del vidrio templado de la puerta. Accion: tomar las medidas de la puerta y reemplazar el vidrio completo.', NULL, 8),
('COC-01', 'COCINA', 'Fuga de gas en tuberia o rubinete', 'Sintoma: olor a gas en la cocina industrial. Causa probable: tuberia de cobre en mal estado o rubinete con fuga por desgaste. Accion: reemplazar el tramo de tuberia, anillos y tuercas de compresion, y verificar hermeticidad con agua jabonosa.', '["REP-073", "REP-074", "REP-075", "REP-077"]', 1),
('COC-02', 'COCINA', 'Quemadores sin fuerza por shiglores obstruidos', 'Sintoma: los quemadores no salen con fuerza y ennegrecen las ollas. Causa probable: shiglores obstruidos u oxigenadores mal regulados. Accion: limpiar o reemplazar los shiglores y regular los oxigenadores de cada quemador.', '["REP-076"]', 2),
('COC-03', 'COCINA', 'Manguera de gas sin valvula reguladora', 'Sintoma: riesgo de fuga en la acometida de gas de la cocina. Causa probable: manguera de gas sin valvula reguladora ni ataque rapido instalados. Accion: instalar manguera con ataque rapido y valvula reguladora, y sellar con teflon.', NULL, 3),
('COC-04', 'COCINA', 'Piloto en mal estado (llama amarilla, hollin)', 'Sintoma: llama amarillenta y presencia de hollin en las ollas. Causa probable: piloto en mal estado o mal ubicado que genera combustion incompleta. Accion: reemplazar el piloto, reubicarlo correctamente y calibrar la llama.', NULL, 4),
('COC-05', 'COCINA', 'Panel de control con error de sonda (PROBE)', 'Sintoma: el panel muestra error de sonda (PROBE) y el equipo se deshabilita. Causa probable: sonda de temperatura danada o mal conectada. Accion: verificar la sonda y su conexion, y reemplazarla si el error persiste tras las pruebas.', NULL, 5),
('COC-06', 'COCINA', 'Tornillos de sujecion de estructura oxidados', 'Sintoma: la estructura de la cocina presenta holgura o riesgo de ruptura. Causa probable: tornillos de sujecion oxidados por el ambiente humedo de la cocina. Accion: reemplazar los tornillos y reforzar la sujecion de la estructura.', NULL, 6),
('COC-07', 'COCINA', 'Bobina de induccion abierta (no calienta)', 'Sintoma: la cocina de induccion no calienta. Causa probable: bobina de induccion abierta o tarjeta electronica en corto. Accion: verificar la continuidad de la bobina y reemplazar la tarjeta electronica si esta danada.', NULL, 7),
('COC-08', 'COCINA', 'Rubinete de piloto con fuga', 'Sintoma: fuga de gas en el sistema de piloto de la cocina. Causa probable: rubinete del piloto desgastado o con roscas danadas. Accion: reemplazar el rubinete del piloto y sellar con teflon amarillo.', '["REP-077"]', 8),
('PLA-01', 'PLANCHA', 'Fuga de gas en valvula o acople de tuberia', 'Sintoma: fuga de gas cerca del acople de la valvula de la plancha o parrilla. Causa probable: valvula de gas suelta del acople o tuerca barrida. Accion: reemplazar la valvula de gas y el acople, y sellar con teflon amarillo.', '["REP-078"]', 1),
('PLA-02', 'PLANCHA', 'Rubinetes desgastados (llama baja o eje trabado)', 'Sintoma: llama baja o irregular en uno o varios quemadores. Causa probable: rubinetes con eje trabado o desgastado por el uso. Accion: reemplazar los rubinetes afectados y calibrar la llama de cada quemador.', '["REP-078"]', 2),
('PLA-03', 'PLANCHA', 'Perillas de control desgastadas', 'Sintoma: dificultad para regular la llama desde las perillas. Causa probable: perillas de control desgastadas que no acoplan bien al rubinete. Accion: reemplazar las perillas de control en acero inoxidable.', '["REP-079"]', 3),
('PLA-04', 'PLANCHA', 'Hi limit danado (no enciende)', 'Sintoma: la plancha no enciende. Causa probable: hi limit (termostato de seguridad) danado que corta la alimentacion. Accion: conectar de forma provisional en directo y reemplazar el hi limit de manera urgente.', NULL, 4),
('PLA-05', 'PLANCHA', 'Empaque de cajonera de base deteriorado', 'Sintoma: la base de la plancha con cajonera pierde temperatura. Causa probable: empaque inferior de la cajonera deteriorado o faltante. Accion: medir y reemplazar el empaque inferior de la cajonera.', '["REP-080"]', 5),
('PLA-06', 'PLANCHA', 'Quemador roto o fisurado', 'Sintoma: uno de los quemadores no enciende o tiene llama irregular. Causa probable: quemador roto o fisurado por fatiga del material. Accion: reemplazar el quemador danado y calibrar la llama del conjunto.', NULL, 6),
('PLA-07', 'PLANCHA', 'Valvula termostatica de quemador central sin apagar', 'Sintoma: el quemador central se queda encendido y no apaga. Causa probable: mecanismo de apertura y cierre de la valvula termostatica danado. Accion: reemplazar la valvula termostatica del quemador central.', NULL, 7),
('PLA-08', 'PLANCHA', 'Polas de nivel desajustadas (plancha desnivelada)', 'Sintoma: la plancha queda desnivelada al abrirla. Causa probable: polas de nivel mal calibradas en el mecanismo de apertura. Accion: calibrar las polas de nivel y verificar el nivel de la superficie de coccion.', NULL, 8),
('MCA-01', 'MESA CALIENTE', 'Clavija o enchufe recalentado, equipo sin funcionar', 'Sintoma: el equipo deja de funcionar y el cuerpo de la clavija esta recalentado. Causa probable: clavija de alimentacion quemada por falso contacto o sobrecarga. Accion: reemplazar la clavija empotrada completa y revisar el punto de conexion.', '["REP-083"]', 1),
('MCA-02', 'MESA CALIENTE', 'Resistencia explotada (no calienta)', 'Sintoma: la mesa caliente no calienta o se apaga sola. Causa probable: resistencia tipo M explotada o con terminales sulfatados. Accion: reemplazar la resistencia tipo M y los terminales de conexion afectados.', '["REP-082"]', 2),
('MCA-03', 'MESA CALIENTE', 'Terminales de resistencia sulfatados por agua', 'Sintoma: la mesa caliente no llega a temperatura. Causa probable: terminales de la resistencia sulfatados por contacto con agua o liquidos. Accion: limpiar o reemplazar los terminales sulfatados y aislar la conexion.', NULL, 3),
('MCA-04', 'MESA CALIENTE', 'Control digital danado por humedad', 'Sintoma: el equipo no enciende y el control digital no responde. Causa probable: elementos electronicos del control digital sulfatados por contacto con agua. Accion: reemplazar el control digital y proteger la conexion contra salpicaduras.', NULL, 4),
('MCA-05', 'MESA CALIENTE', 'Sonda de control danada', 'Sintoma: la mesa caliente no regula bien la temperatura. Causa probable: sonda del control digital (full gauge) danada. Accion: reemplazar la sonda del control y calibrar la temperatura de trabajo.', '["REP-085"]', 5),
('MCA-06', 'MESA CALIENTE', 'Termostato defectuoso', 'Sintoma: la mesa caliente se sobrecalienta o no corta la temperatura. Causa probable: termostato en mal estado. Accion: reemplazar el termostato de 0 a 90 grados y probar el corte de temperatura.', '["REP-084"]', 6),
('MCA-07', 'MESA CALIENTE', 'Switch de poder con pines rotos', 'Sintoma: el equipo no enciende. Causa probable: switch de poder con pines rotos o sobrecalentados. Accion: reemplazar el switch de poder y revisar el circuito de alimentacion.', NULL, 7),
('MCA-08', 'MESA CALIENTE', 'Cables expuestos por manguera bx deteriorada', 'Sintoma: riesgo electrico por cables expuestos junto a la mesa caliente. Causa probable: manguera bx de proteccion de cables deteriorada o faltante. Accion: instalar manguera bx nueva para recubrir los cables expuestos.', NULL, 8),
('ARR-01', 'OLLA ARROCERA', 'Piloto o flauta con fuga de gas', 'Sintoma: fuga de gas en el sistema de piloto de la olla arrocera. Causa probable: piloto o flauta deteriorados por el uso continuo. Accion: reemplazar el tubo piloto y el porta electrodo, y verificar la hermeticidad.', '["REP-086"]', 1),
('ARR-02', 'OLLA ARROCERA', 'Olla interna desgastada (el arroz se pega)', 'Sintoma: el arroz se pega dentro de la olla. Causa probable: desgaste del recubrimiento interno de la olla. Accion: evaluar el estado de la olla interna y reemplazarla si el desgaste es irreversible.', '["REP-089"]', 2),
('ARR-03', 'OLLA ARROCERA', 'Pata de la olla rota (inestabilidad)', 'Sintoma: la olla arrocera se encuentra inestable. Causa probable: una de las patas de apoyo rota o fisurada. Accion: reemplazar la pata danada y verificar la nivelacion del equipo.', '["REP-087"]', 3),
('ARR-04', 'OLLA ARROCERA', 'Ciclor de paso de gas obstruido o danado', 'Sintoma: el gas no pasa correctamente hacia el quemador de la olla. Causa probable: ciclor recto del sistema de paso de gas obstruido o danado. Accion: reemplazar el ciclor recto y verificar el flujo de gas.', '["REP-088"]', 4),
('ARR-05', 'OLLA ARROCERA', 'Bimetalico sucio (sonido anormal, no corta calor)', 'Sintoma: la olla emite sonido anormal o no corta el calor al terminar la coccion. Causa probable: bimetalico sucio que no acciona el sistema automatico. Accion: limpiar el bimetalico y el mecanismo automatico, y regular la llama del piloto.', NULL, 5),
('ARR-06', 'OLLA ARROCERA', 'Manguera de gas mal puesta o estrangulada', 'Sintoma: fuga de gas o falta de encendido en la olla arrocera. Causa probable: manguera de gas mal puesta o estrangulada por contacto con otro equipo. Accion: corregir el tendido de la manguera y ajustar la abrazadera metalica.', NULL, 6),
('ARR-07', 'OLLA ARROCERA', 'Shiglor de piloto en mal estado (llama amarilla)', 'Sintoma: el piloto presenta llama demasiado amarilla con hollin. Causa probable: shiglor de piloto en mal estado que altera la mezcla aire-gas. Accion: reemplazar el shiglor del piloto y calibrar la llama.', NULL, 7),
('ARR-08', 'OLLA ARROCERA', 'Sistema de ignicion obstruido por suciedad', 'Sintoma: la olla arrocera no enciende. Causa probable: sistema de ignicion (chispero) obstruido por suciedad acumulada. Accion: desmontar y limpiar el sistema de ignicion, y realizar pruebas de encendido.', '["REP-086"]', 8),
('EXH-01', 'EXHIBIDOR', 'Empaque de puerta deteriorado', 'Sintoma: el exhibidor pierde temperatura por la puerta. Causa probable: empaque de puerta en mal estado tipo ECASA. Accion: tomar medidas y reemplazar el empaque de puerta correspondiente.', '["REP-090"]', 1),
('EXH-02', 'EXHIBIDOR', 'Foco LED de iluminacion quemado', 'Sintoma: la iluminacion interna del exhibidor no enciende. Causa probable: foco LED quemado o con falso contacto. Accion: reemplazar el foco LED y verificar el circuito de iluminacion.', '["REP-091"]', 2),
('EXH-03', 'EXHIBIDOR', 'Boya (sensor de nivel) de desague defectuosa', 'Sintoma: desbordamiento de agua en la bandeja de drenaje. Causa probable: boya sensor de nivel defectuosa que no corta el llenado. Accion: reemplazar la boya y realizar la conexion al contactor correspondiente.', NULL, 3),
('EXH-04', 'EXHIBIDOR', 'Resistencia de cordon quemada', 'Sintoma: el sistema electrico presenta cable de acometida quemado. Causa probable: resistencia de cordon y su cableado quemados por sobrecarga. Accion: reemplazar la resistencia de cordon y el cable de acometida asociado.', NULL, 4),
('EXH-05', 'EXHIBIDOR', 'Control digital descalibrado (corta antes de temperatura)', 'Sintoma: el exhibidor no llega a la temperatura correcta. Causa probable: control full gauge descalibrado que corta el compresor antes de tiempo. Accion: reemplazar el control full gauge y calibrar el set point.', '["REP-092"]', 5),
('APA-01', 'MESA DE APANADO', 'Motor servo no arranca por tarjeta sulfatada', 'Sintoma: el motor de la mesa de apanado no se activa aunque llega voltaje al variador. Causa probable: tarjeta electronica sulfatada por humedad de harina. Accion: limpiar o reemplazar la tarjeta electronica y verificar el motor servo.', '["REP-093"]', 1),
('APA-02', 'MESA DE APANADO', 'Tina de la mesa derretida o deformada', 'Sintoma: la tina de la mesa de apanado presenta deformacion. Causa probable: exposicion a calor excesivo o material de baja resistencia. Accion: reemplazar la tina de la mesa de apanado.', '["REP-094"]', 2),
('APA-03', 'MESA DE APANADO', 'Cepillo de tamiz atorado o desgastado', 'Sintoma: el cepillo de la mesa de apanado se traba durante la operacion. Causa probable: acople del cepillo mal colocado o desgastado. Accion: reemplazar el conjunto de cepillos del tamiz y verificar el acople del motor.', NULL, 3),
('APA-04', 'MESA DE APANADO', 'Toma corriente y cable de alimentacion danados', 'Sintoma: la mesa de apanado no enciende. Causa probable: toma corriente y cable de alimentacion deteriorados u oxidados. Accion: reemplazar el toma corriente y el cable de alimentacion completos.', '["REP-095"]', 4),
('APA-05', 'MESA DE APANADO', 'Caja de transmision con pinones danados', 'Sintoma: el motor gira pero no transmite fuerza al cepillo. Causa probable: pinones de la caja de transmision danados por desgaste. Accion: reemplazar el motor con su caja de transmision y realizar pruebas de funcionamiento.', NULL, 5),
('LAV-01', 'LAVAVAJILLAS', 'Presostato de nivel de agua danado', 'Sintoma: el equipo presenta error de ingreso de agua o fugas por el presostato. Causa probable: presostato de nivel de agua danado o trampa de aire fisurada. Accion: reemplazar el presostato y la trampa de aire, y probar el ciclo de llenado.', '["REP-096"]', 1),
('LAV-02', 'LAVAVAJILLAS', 'Bomba de desague obstruida o danada', 'Sintoma: el agua no drena al finalizar el ciclo de lavado. Causa probable: bomba de desague obstruida por residuos o con el eje danado. Accion: desmontar, limpiar y reemplazar la bomba de desague si no recupera el drenaje.', '["REP-097"]', 2),
('LAV-03', 'LAVAVAJILLAS', 'Resistencia de caldera con cortocircuito', 'Sintoma: la resistencia permanece encendida todo el tiempo. Causa probable: cortocircuito entre cables de la resistencia que dana pistas de la tarjeta. Accion: reemplazar la resistencia de caldera y revisar la tarjeta electronica asociada.', '["REP-098"]', 3),
('LAV-04', 'LAVAVAJILLAS', 'Fuga de agua por tuberia o acoples flojos', 'Sintoma: fuga de agua en la base del lavavajillas. Causa probable: acoples flojos o tuberia de 3/8 con perforaciones. Accion: ajustar o reemplazar la tuberia y los acoples afectados.', NULL, 4),
('LAV-05', 'LAVAVAJILLAS', 'Probe de temperatura en corto (error 08)', 'Sintoma: el panel muestra error de temperatura con la sonda en corto. Causa probable: probe de temperatura en corto por humedad o desgaste. Accion: verificar el ohmiaje del probe y reemplazarlo si esta en corto.', NULL, 5),
('TOS-01', 'TOSTADORA', 'Switch de encendido danado (recalentado)', 'Sintoma: el switch de encendido se recalienta y el equipo queda conectado en directo. Causa probable: switch de encendido con pines recalentados o quemados. Accion: reemplazar el switch de encendido y el tramo de cable afectado.', '["REP-099"]', 1),
('TOS-02', 'TOSTADORA', 'Cables de alimentacion recalentados', 'Sintoma: la tostadora se apaga y enciende de forma intermitente. Causa probable: cables de alimentacion recalentados por conexiones flojas. Accion: reemplazar el tramo de cable de alta temperatura y ajustar las conexiones.', NULL, 2),
('TOS-03', 'TOSTADORA', 'Sonda RTD de temperatura danada', 'Sintoma: la tostadora no controla bien la temperatura de coccion. Causa probable: sonda RTD de temperatura danada o con lectura erratica. Accion: reemplazar la sonda RTD con cable de 48 pulgadas.', '["REP-100"]', 3),
('TOS-04', 'TOSTADORA', 'Transformador de tarjeta danado (no enciende)', 'Sintoma: la tostadora no enciende. Causa probable: transformador de la tarjeta de control danado. Accion: reemplazar el transformador y verificar la alimentacion de la tarjeta.', '["REP-101"]', 4),
('TOS-05', 'TOSTADORA', 'Manguera bx de cableado rota (olor a quemado)', 'Sintoma: olor a quemado y cables expuestos junto al equipo. Causa probable: manguera bx de proteccion del cableado rota por el calor. Accion: reemplazar la manguera bx y el tramo de cable de alta temperatura.', NULL, 5),
('MIC-01', 'MICROONDAS', 'Magnetron danado (no calienta)', 'Sintoma: el microondas no calienta el producto. Causa probable: magnetron fuera de rango de trabajo o con la antena quemada. Accion: reemplazar el magnetron segun el modelo del equipo y probar el calentamiento.', '["REP-102"]', 1),
('MIC-02', 'MICROONDAS', 'Microswitch de puerta danado', 'Sintoma: el equipo no calienta aunque el transformador entrega voltaje correcto. Causa probable: microswitch de puerta que no ancla correctamente el cierre. Accion: reemplazar el microswitch de puerta y verificar el cierre de seguridad.', '["REP-103"]', 2),
('MIC-03', 'MICROONDAS', 'Estructura interna deteriorada (arcos electricos)', 'Sintoma: se generan arcos electricos (chispas) dentro de la cavidad. Causa probable: estructura interna del microondas deteriorada por oxido o impacto. Accion: evaluar si la estructura es reparable; si no, dar de baja el equipo.', NULL, 3),
('MIC-04', 'MICROONDAS', 'Fusible quemado (no enciende)', 'Sintoma: el microondas no enciende. Causa probable: fusible de proteccion quemado por sobrecorriente. Accion: reemplazar el fusible y verificar la causa de la sobrecorriente antes de habilitar el equipo.', NULL, 4),
('GAS-01', 'GAS E INSTALACIONES', 'Fuga de gas en rubinete de equipo de coccion', 'Sintoma: fuga de gas detectada en el rubinete de alimentacion de un equipo de coccion. Causa probable: rubinete desgastado que pierde hermeticidad. Accion: reemplazar el rubinete y verificar hermeticidad con agua jabonosa.', '["REP-104"]', 1),
('GAS-02', 'GAS E INSTALACIONES', 'Termostato de termotanque recalentado', 'Sintoma: el termotanque no corta la alimentacion de las resistencias por temperatura. Causa probable: termostato recalentado en sus bordes que no censa correctamente. Accion: reemplazar el termostato del termotanque y aislar las conexiones.', '["REP-105"]', 2),
('GAS-03', 'GAS E INSTALACIONES', 'Botonera de montacargas rota', 'Sintoma: el montacargas no responde a los mandos. Causa probable: botonera de control rota o con boton de emergencia salido. Accion: reemplazar la botonera y su caja de proteccion metalica.', NULL, 3),
('GAS-04', 'GAS E INSTALACIONES', 'Final de carrera danado en montacargas', 'Sintoma: el montacargas presenta fallas al subir o bajar a un nivel determinado. Causa probable: final de carrera danado con falsos contactos. Accion: reemplazar el final de carrera afectado y probar el recorrido completo.', NULL, 4),
('GAS-05', 'GAS E INSTALACIONES', 'Valvula de alivio activada por presion de agua', 'Sintoma: activacion de la valvula de alivio del termotanque. Causa probable: acumulacion de presion de agua por termostato que no corta la resistencia a tiempo. Accion: revisar el termostato, corregir la falla y verificar la valvula de alivio.', '["REP-105"]', 5),
('DIS-01', 'DISPENSADOR DE BEBIDAS', 'Display no enciende (falla de alimentacion al tablero)', 'Sintoma: el display del dispensador no enciende. Causa probable: falla de alimentacion al tablero de control. Accion: verificar el voltaje de entrada al tablero y reemplazar el conjunto de tablero de control si no recupera encendido.', '["REP-106"]', 1),
('DIS-02', 'DISPENSADOR DE BEBIDAS', 'Tablero de control no envia senales de funcionamiento', 'Sintoma: el equipo no manda las senales necesarias para funcionar aunque el display intenta encender. Causa probable: falla interna del tablero de control. Accion: revisar las conexiones internas y reemplazar el tablero de control.', '["REP-106"]', 2),
('DIS-03', 'DISPENSADOR DE BEBIDAS', 'Falla recurrente de tablero de control', 'Sintoma: el equipo repite la misma falla de encendido tras una intervencion previa. Causa probable: tablero de control con dano recurrente no resuelto en la intervencion anterior. Accion: reemplazar el tablero de control completo en lugar de repararlo.', '["REP-106"]', 3),
('DIS-04', 'DISPENSADOR DE BEBIDAS', 'Protector o dispensador de jabon mal instalado', 'Sintoma: el protector del dispensador de jabon no queda fijo en su lugar. Causa probable: instalacion incompleta del dispensador o su protector. Accion: instalar correctamente el dispensador de jabon y su protector, y verificar la sujecion.', NULL, 4),
('CAM-01', 'CAMPANA', 'Protector termico activado o danado (no enciende)', 'Sintoma: la campana no enciende. Causa probable: protector termico del motor activado o en corto, impidiendo el accionamiento de la bobina. Accion: verificar el protector termico, corregir la conexion y reemplazarlo si no acciona correctamente.', NULL, 1),
('CAM-02', 'CAMPANA', 'Switch de encendido con falso contacto', 'Sintoma: falso contacto al accionar el switch de encendido de la campana. Causa probable: contactos del switch desgastados o sucios. Accion: limpiar o reemplazar el switch de encendido y verificar el circuito de control.', NULL, 2),
('CAM-03', 'CAMPANA', 'Cable de alimentacion o reflector con aislamiento danado', 'Sintoma: descarga a tierra al tocar la estructura de la campana. Causa probable: aislamiento del cable de reflector, timer o alimentacion deteriorado. Accion: reemplazar el tramo de cable danado, aislar conexiones y cambiar capuchones.', NULL, 3),
('CAM-04', 'CAMPANA', 'Lampara o reflector de iluminacion quemado', 'Sintoma: la campana no ilumina la zona de coccion. Causa probable: lampara o reflector quemado por el calor y el uso continuo. Accion: reemplazar la lampara y/o el reflector, y verificar el circuito de iluminacion.', '["REP-107", "REP-108"]', 4),
('BAT-01', 'BATIDORA', 'Falla en tarjeta de control (display sin informacion)', 'Sintoma: el display no muestra la temperatura ni la informacion de programacion. Causa probable: falla o suciedad en la tarjeta electronica de control. Accion: limpiar la tarjeta, conectores y terminales; reemplazar el conjunto de placa de control si no recupera.', '["REP-109"]', 1),
('BAT-02', 'BATIDORA', 'Engranajes de caja de transmision desgastados', 'Sintoma: ruido o perdida de fuerza en el mecanismo de batido. Causa probable: desgaste de los engranajes de la caja de transmision por falta de lubricacion. Accion: lubricar o reemplazar los engranajes de la caja de transmision y realizar pruebas de funcionamiento.', NULL, 2),
('BAT-03', 'BATIDORA', 'Carbones de motor desgastados', 'Sintoma: el motor pierde fuerza o presenta chispeo interno. Causa probable: carbones de motor desgastados por uso prolongado. Accion: revisar el estado de los carbones y reemplazarlos si estan por debajo de la longitud minima.', NULL, 3),
('BAT-04', 'BATIDORA', 'Rodamientos secos o desgastados (ruido en el eje)', 'Sintoma: ruido en el eje de batido durante la operacion. Causa probable: rodamientos secos o desgastados por falta de lubricacion periodica. Accion: lubricar los rodamientos y reemplazarlos si presentan juego excesivo.', NULL, 4)
